using System; namespace Domain.MainBoundedContext.InventoryModule.Aggregates.AssetAgg { public static class AssetFactory { public static Asset Create(string name,string remarks,string assetType,string supplier,string department,string picturePath,string glAccount,string serialNumber,string manufacturer,string model,string tagNumber,string location,decimal purchasePrice,decimal residualValue) { var x=new Asset(); x.GenerateNewIdentity(); x.Name=name; x.Remarks=remarks; x.AssetType=assetType; x.Supplier=supplier; x.Department=department; x.PicturePath=picturePath; x.GLAccount=glAccount; x.SerialNumber=serialNumber; x.Manufacturer=manufacturer; x.Model=model; x.TagNumber=tagNumber; x.Location=location; x.PurchasePrice=purchasePrice; x.ResidualValue=residualValue; x.CreatedDate=DateTime.Now; return x; } } }
